score_cols=["entry_number","insanity","absurdity","danger","authoritarianism","lawlessness","credibility_risk","recency_intensity","impact_scope","rationale_short","rationale_detail"]
source_cols=["entry_number","url","title","publisher","date_published","source_type"]

entry_vals=[]; score_vals=[]; source_vals=[]; keyword_vals=[]
for e in entries:
    m=metrics[e["metrics_key"]]
    e["impressions"]=m["impressions"]; e["reach_estimate"]=m["reach_estimate"]; e["financial_cost_usd"]=m["financial_cost_usd"]; e["public_reaction"]=m["public_reaction"]; e["age"]=calc_age(e["date_start"])
    s=e["scores"]
    entry_vals.append("("+", ".join([
        str(e["entry_number"]),f"'{sql_escape(e['title'])}'",f"'{e['date_start']}'",f"'{e['date_end']}'",f"'{sql_escape(e['synopsis'])}'",f"'{sql_escape(e['rationale'])}'",f"'{sql_escape(e['category'])}'",f"'{sql_escape(e['subcategory'])}'",arr_sql(e["keywords"]),str(e["age"]),f"'{sql_escape(e['phase'])}'",str(e["impressions"]),str(e["reach_estimate"]),str(e["financial_cost_usd"]),json_sql(e["public_reaction"]),"NULL","ARRAY[]::text[]",json_sql(s)
    ])+")")
    score_vals.append("("+", ".join([
        str(e["entry_number"]),str(s["insanity"]),str(s["absurdity"]),str(s["danger"]),str(s["authoritarianism"]),str(s["lawlessness"]),str(s["credibility_risk"]),str(s["recency_intensity"]),str(s["impact_scope"]),f"'{sql_escape(s['rationale_short'])}'",f"'{sql_escape(s['rationale_detail'])}'"
    ])+")")
    source_vals.append("("+", ".join([
        str(e["entry_number"]),f"'{sql_escape(e['source_url'])}'",f"'{sql_escape(e['source_title'])}'",f"'{sql_escape(e['source_publisher'])}'",f"'{e['date_start']}'",f"'news'"
    ])+")")
    for kw in e["keywords"]: keyword_vals.append("("+", ".join([str(e["entry_number"]),f"'{sql_escape(kw)}'"])+")")

sql_entries="INSERT INTO public.trump_entries ("+", ".join(entry_cols)+") VALUES\n"+",\n".join(entry_vals)+"\nON CONFLICT DO NOTHING;"
sql_scores="INSERT INTO public.trump_individual_scores ("+", ".join(score_cols)+") VALUES\n"+",\n".join(score_vals)+"\nON CONFLICT DO NOTHING;"
sql_sources="INSERT INTO public.trump_sources ("+", ".join(source_cols)+") VALUES\n"+",\n".join(source_vals)+";"
sql_keywords="INSERT INTO public.trump_keywords (entry_number, keyword) VALUES\n"+",\n".join(keyword_vals)+"\nON CONFLICT DO NOTHING;"
print(json.dumps([sql_entries,sql_scores,sql_sources,sql_keywords],indent=2))
